body.vi:
Để điều hướng quân Mã trên bàn cờ 8x8, thay vì viết 8 nhánh `if-else` cồng kềnh, ta định nghĩa hai mảng 1 chiều hằng số chứa độ dịch dòng (`rowOffset`) và cột (`colOffset`):
```cpp
constexpr std::array<int, 8> dRow{-1, -2, -2, -1, 1, 2, 2, 1};
constexpr std::array<int, 8> dCol{2, 1, -1, -2, -2, -1, 1, 2};
```
Mỗi nước đi $k \in [0, 7]$ biến đổi tọa độ hiện tại thành `(r + dRow[k], c + dCol[k])`. Trước khi thực hiện, cần kiểm tra tọa độ đích: $0 \le r_{new} < 8$ và $0 \le c_{new} < 8$, đồng thời ô đó chưa từng được ghé thăm (`board[r][c] == 0`).

body.en:
To navigate a knight across an 8x8 chessboard, instead of tedious nested branches, we use two coordinate offset lookup arrays:
```cpp
constexpr std::array<int, 8> dRow{-1, -2, -2, -1, 1, 2, 2, 1};
constexpr std::array<int, 8> dCol{2, 1, -1, -2, -2, -1, 1, 2};
```
Every move index $k \in [0, 7]$ calculates candidate square `(r + dRow[k], c + dCol[k])`. Before advancing, boundaries ($0 \le r_{new} < 8$, $0 \le c_{new} < 8$) and occupancy (`board[r][c] == 0`) must be verified.

example.code:
#include <iostream>
#include <array>

constexpr int N = 8;
constexpr std::array<int, 8> dRow{-1, -2, -2, -1, 1, 2, 2, 1};
constexpr std::array<int, 8> dCol{2, 1, -1, -2, -2, -1, 1, 2};

bool isValid(int r, int c, const std::array<std::array<int, N>, N>& board) {
    return (r >= 0 && r < N && c >= 0 && c < N && board[r][c] == 0);
}

int getAccessibility(int r, int c, const std::array<std::array<int, N>, N>& board) {
    int count = 0;
    for (int i = 0; i < 8; ++i) {
        if (isValid(r + dRow[i], c + dCol[i], board)) {
            ++count;
        }
    }
    return count;
}

int main() {
    std::array<std::array<int, N>, N> board{};
    int r = 0, c = 0;
    board[r][c] = 1;
    int totalMoves = 1;

    for (int step = 2; step <= N * N; ++step) {
        int minDeg = 9;
        int bestIdx = -1;

        for (int i = 0; i < 8; ++i) {
            int nr = r + dRow[i];
            int nc = c + dCol[i];
            if (isValid(nr, nc, board)) {
                int deg = getAccessibility(nr, nc, board);
                if (deg < minDeg) {
                    minDeg = deg;
                    bestIdx = i;
                }
            }
        }

        if (bestIdx == -1) {
            break;
        }
        r += dRow[bestIdx];
        c += dCol[bestIdx];
        board[r][c] = step;
        ++totalMoves;
    }

    std::cout << "Tour moves completed: " << totalMoves << "\n";
    std::cout << "Final square at (7,7): " << board[7][7] << "\n";
    return 0;
}

#include <iostream>
#include <vector>
#include <array>

void runSieve(int maxVal) {
    std::vector<bool> isPrime(maxVal + 1, true);
    isPrime[0] = false;
    isPrime[1] = false;

    for (int p = 2; p * p <= maxVal; ++p) {
        if (isPrime[p]) {
            for (int multiple = p * p; multiple <= maxVal; multiple += p) {
                isPrime[multiple] = false;
            }
        }
    }

    std::cout << "Primes up to 30: ";
    for (int i = 2; i <= 30; ++i) {
        if (isPrime[i]) {
            std::cout << i << ' ';
        }
    }
    std::cout << '\n';
}

int main() {
    runSieve(30);

    std::array<int, 10> rawInput{5, 12, 5, 3, 19, 3, 12, 7, 20, 1};
    std::array<bool, 21> seen{};
    std::vector<int> uniqueList;

    for (int val : rawInput) {
        if (!seen[val]) {
            seen[val] = true;
            uniqueList.push_back(val);
        }
    }

    std::cout << "Unique items: ";
    for (int val : uniqueList) {
        std::cout << val << ' ';
    }
    std::cout << '\n';
    return 0;
}

#include <iostream>
#include <string_view>
#include <cctype>
#include <array>

int recursiveMinimum(const int arr[], int size) {
    if (size == 1) {
        return arr[0];
    }
    int minRest = recursiveMinimum(arr, size - 1);
    return (arr[size - 1] < minRest) ? arr[size - 1] : minRest;
}

int testPalindrome(std::string_view s, int left, int right) {
    if (left >= right) {
        return 1;
    }
    if (!std::isalnum(static_cast<unsigned char>(s[left]))) {
        return testPalindrome(s, left + 1, right);
    }
    if (!std::isalnum(static_cast<unsigned char>(s[right]))) {
        return testPalindrome(s, left, right - 1);
    }
    if (std::tolower(static_cast<unsigned char>(s[left])) !=
        std::tolower(static_cast<unsigned char>(s[right]))) {
        return 0;
    }
    return testPalindrome(s, left + 1, right - 1);
}

int main() {
    std::array<int, 5> numbers{45, 12, 89, 7, 23};
    std::cout << "Min value: " << recursiveMinimum(numbers.data(), numbers.size()) << '\n';

    std::string_view phrase = "radar";
    std::cout << "Is palindrome ('radar'): "
              << testPalindrome(phrase, 0, phrase.size() - 1) << '\n';
    return 0;
}
